        int errors = 0;
        int test_int = 1;
        #pragma omp target parallel map(tofrom: errors)
        {
                #pragma omp scope firstprivate(test_int)
                {
                        test_int += 1;
                        OMPVV_TEST_AND_SET(errors,test_int != 2);
                }
