 7  // reduction(inscan) clause. The test peforms the scan operation with the add
 8  // operator and then checks the results against an expected result from a
 9  // sequentially-computed prefix sum.
10  //
11  ////===----------------------------------------------------------------------===//
12  #include <assert.h>
