26    int b[N];
27
28    for (int i = 0; i < N; i++) {
29      a[i] = i;
30      b[i] = 0;
31    }
32
33  #pragma omp parallel for simd reduction(inscan, +: x) num_threads(OMPVV_NUM_THREADS_HOST)
34    for (int i = 0; i < N; i++) {
35      x += a[i];
36  #pragma omp scan inclusive(x)
37      b[i] = x;
38    }
