 2  //
 3  // OpenMP API Version 5.0 Nov 2018
 4  //
 5  // This test checks the taskloop simd directive with the `in_reduction`
 6  // reduction participation clause. It performs simple array operations which
 7  // are added to a reduction variable in a taskloop with the in_reduction
 8  // clause.
 9  //
10  ////===----------------------------------------------------------------------===//
11  #include <assert.h>
12  #include <omp.h>
13  #include <stdio.h>
14  #include <stdlib.h>
15  #include "ompvv.h"
16
17  #define N 1024
18
19  int test_taskloop_simd_in_reduction() {
20    OMPVV_INFOMSG("test_taskloop_simd_in_reduction");
21    int errors = 0;
22    int num_threads = -1;
23    int y[N];
24    int z[N];
25    int sum = 0;
26    int expected_sum = 0;
27
28    for (int i = 0; i < N; i++) {
29      y[i] = i + 1;
30      z[i] = 2*(i + 1);
31    }
32
33  #pragma omp parallel reduction(task, +: sum) num_threads(OMPVV_NUM_THREADS_HOST) shared(y, z, num_threads)
34    {
35  #pragma omp master
36      {
37  #pragma omp taskloop simd in_reduction(+: sum)
38        for (int i = 0; i < N; i++) {
39          sum += y[i]*z[i];
40        }
41        num_threads = omp_get_num_threads();
42      }
43    }
44
45    for (int i = 0; i < N; i++) {
46      expected_sum += y[i]*z[i];
47    }
48
49    OMPVV_TEST_AND_SET_VERBOSE(errors, sum != expected_sum);
50
51    OMPVV_WARNING_IF(num_threads == 1, "Test ran with one thread, so parallelism of taskloop can't be guaranteed.");
52    OMPVV_ERROR_IF(num_threads < 1, "Test returned an invalid number of threads.");
53    OMPVV_TEST_AND_SET_VERBOSE(errors, num_threads < 1);
54
55    return errors;
56  }
57
58
59  int main() {
60    int errors = 0;
61
62    OMPVV_TEST_AND_SET_VERBOSE(errors, test_taskloop_simd_in_reduction());
63
64    OMPVV_REPORT_AND_RETURN(errors);
65  }

