 3  // OpenMP API Version 5.0 Nov 2018
 4  //
 5  // This test checks the taskloop simd combined directive with the reduction clause specified.
 6  //
 7  ////===----------------------------------------------------------------------===//
 8
 9  #include <omp.h>
10  #include <stdio.h>
11  #include <stdlib.h>
12  #include "ompvv.h"
13
14  #define N 1024
15
16  int test_taskloop_reduction() {
17
18     int errors = 0;
19     int a[N];
20     int b[N];
21     int sum = 0;
22     int num_threads = -1;
23     int real_sum = 0;
24
25     for (int i = 0; i < N; i++) {
26        a[i] = 5;
27        b[i] = i * 2;
28     }
29
30  #pragma omp parallel num_threads(OMPVV_NUM_THREADS_HOST) shared(a, b, num_threads, sum)
31  {
32     #pragma omp single
33     #pragma omp taskloop simd reduction(+:sum)
34     for (int i = 0; i < N; i++) {
35        #pragma omp atomic
36        sum += a[i]*b[i];
37     }
38     num_threads = omp_get_num_threads();
39
40     #pragma omp single
41     #pragma omp taskloop simd reduction(+:sum)
42     for (int i = 0; i < N; i++) {
43        #pragma omp atomic
44        sum++;
45     }
46
47  }
48
49     real_sum += N;
50
51     for (int i = 0; i < N; i++) {
52        real_sum += a[i]*b[i];
53     }
54
55     OMPVV_TEST_AND_SET_VERBOSE(errors, sum != real_sum);
56
57     OMPVV_WARNING_IF(num_threads == 1, "Test ran with one thread, so parallelism of taskloop can't be guaranteed.");
58     OMPVV_ERROR_IF(num_threads < 1, "Test returned an invalid number of threads.");
59     OMPVV_TEST_AND_SET_VERBOSE(errors, num_threads < 1);
60
61
62     return errors;
63  }
64
65
66  int main() {
67
68     int errors = 0;
69
70     OMPVV_TEST_AND_SET_VERBOSE(errors, test_taskloop_reduction());
71
72     OMPVV_REPORT_AND_RETURN(errors);
73
74  }

