35     for (int i = 0; i < N; i++) {
36        sum += a[i]*b[i];
37     }
38     num_threads = omp_get_num_threads();
39
40     #pragma omp single
41     #pragma omp taskloop reduction(+:sum)
42     for (int i = 0; i < N; i++) {
