 1  //===--- test_taskloop_in_reduction.c -------------------------------------------===//
 2  //
 3  // OpenMP API Version 5.0 Nov 2018
 4  //
 5  // This test checks the taskloop directive with the `in_reduction` reduction
 6  // participation clause. It performs simple array operations which are added
 7  // to a reduction variable in a taskloop with the in_reduction clause.
 8  //
 9  ////===----------------------------------------------------------------------===//
10  #include <assert.h>
11  #include <omp.h>
12  #include <stdio.h>
13  #include <stdlib.h>
14  #include "ompvv.h"
15
16  #define N 1024
17
18  int test_taskloop_in_reduction() {
19    OMPVV_INFOMSG("test_taskloop_in_reduction");
20    int errors = 0;
21    int num_threads = -1;
22    int y[N];
23    int z[N];
24    int sum = 0;
25    int expected_sum = 0;
26
27    for (int i = 0; i < N; i++) {
28      y[i] = i + 1;
29      z[i] = 2*(i + 1);
30    }
31
32  #pragma omp parallel reduction(task, +: sum) num_threads(OMPVV_NUM_THREADS_HOST) shared(y, z, num_threads)
33    {
34  #pragma omp master
35      {
36  #pragma omp taskloop in_reduction(+: sum)
37        for (int i = 0; i < N; i++) {
38          sum += y[i]*z[i];
39        }
40        num_threads = omp_get_num_threads();
41      }
42    }
43
44    for (int i = 0; i < N; i++) {
45      expected_sum += y[i]*z[i];
46    }
47
48    OMPVV_TEST_AND_SET_VERBOSE(errors, sum != expected_sum);
49
50    OMPVV_WARNING_IF(num_threads == 1, "Test ran with one thread, so parallelism of taskloop can't be guaranteed.");
51    OMPVV_ERROR_IF(num_threads < 1, "Test returned an invalid number of threads.");
52    OMPVV_TEST_AND_SET_VERBOSE(errors, num_threads < 1);
53
54    return errors;
55  }
56
57
58  int main() {
59    int errors = 0;
60
61    OMPVV_TEST_AND_SET_VERBOSE(errors, test_taskloop_in_reduction());
62
63    OMPVV_REPORT_AND_RETURN(errors);
64  }

