    }

    #pragma omp target map(tofrom: arr)
    #pragma omp parallel num_threads(OMPVV_NUM_THREADS_DEVICE)
    #pragma omp for
    for(i = 0; i < N; i++){
        arr[i] = arr[i]*2;
    }
    // Test that no issues were caused from using assumes directive
    for(i = 0; i < N; i++){
        OMPVV_TEST_AND_SET(errors, arr[i] != i*2);
    }
