   {
      int thrd = omp_get_thread_num();
       if (thrd == 0) {
          y = 1;
          #pragma omp atomic write seq_cst
          x = 10;
       } else {
          while (y != 5) {
            #pragma omp atomic compare seq_cst fail(acquire)
            if(y == 1){
               y = 5;
            }
          }
          OMPVV_TEST_AND_SET(errors, x != 10);
          OMPVV_TEST_AND_SET(errors, y != 5);
       }
   }
   return errors;
}


