    for (int x = 0; x < N; ++x) {
      for (int y = 0; y < 16; ++y) {
        if (rand() / (double) RAND_MAX < false_margin) {
          a[x] += (1 << y);
          have_true = 1;
        } else {
          have_false = 1;
        }
      }
      num_teams[x] = -x;
