//
//===------------------------------------------------------------------------===//
#include <stdio.h>
#include "omp.h"
#include "ompvv.h"

#define N 1024


int Runtst(int gpu) {
  int errors = 0;
  int *A = (int *)malloc(sizeof(int) * N);
  for (int i = 0; i < N; ++i) {
    A[i] = i;
  }

#pragma omp target data map(tofrom: A[0:N]) device(gpu)
  {
    #pragma omp target parallel for device(gpu)
    for (int i = 0; i < N; ++i) {
      A[i] = A[i] * A[i];
    }
  }

  // Verification

