// variable in the reduction clause is properly reduced using the add
// operator. This test checks the above in a target context.
//
////===----------------------------------------------------------------------===//

#include <omp.h>
#include <stdio.h>
#include <stdlib.h>
#include "ompvv.h"
#include <math.h>

#define N 1024

int test_add() {
  int a[N];
  int b[N];
  int total = 0;
  int expect_total = 0;
  int errors = 0;
  int num_threads[N];

  for (int x = 0; x < N; ++x) {
    a[x] = 1;
    b[x] = x;
    num_threads[x] = -1;
  }

#pragma omp target parallel num_threads(OMPVV_NUM_THREADS_DEVICE) map(tofrom: total, a, b, num_threads)
  {
#pragma omp loop reduction(+:total)
    for (int x = 0; x < N; ++x) {
      total += a[x] + b[x];
    }
#pragma omp for
    for (int x = 0; x < N; ++x) {
