  int tested_true = 0;
  int tested_false = 0;
  int itr_count = 0;
  srand(1);

  while ((!tested_true || !tested_false) && (itr_count < THRESHOLD)) {
    for (int x = 0; x < N; ++x) {
      a[x] = rand() / (double)(RAND_MAX) > true_margin;
      num_threads[x] = -x;
    }

    char result = 0;
    char host_result = 0;

#pragma omp target parallel num_threads(OMPVV_NUM_THREADS_DEVICE) map(tofrom: result, a, num_threads)
    {
