    // a, b, and c array initialization
    for (i = 0; i < SIZE; i++) {
      a[i] = SIZE - i;
      b[i] = i;
      c[i] = -1;
    }
#pragma omp target data if(map_size > SIZE_THRESHOLD) map(to: map_size)  \
        map(tofrom: c[0:map_size])                             \
        map(to: a[0:map_size], b[0:map_size])
