  OMPVV_TEST_AND_SET_VERBOSE(errors, test_target_data_map_if_nested(isOffloading) != 0);
  OMPVV_TEST_AND_SET_VERBOSE(errors, test_target_data_map_if_simple(isOffloading) != 0);

  OMPVV_REPORT_AND_RETURN(errors);
}

