      c[j] = a[j] + b[j];
    }
  }

  for (int i = 0; i < N; i++) {
    OMPVV_TEST_AND_SET_VERBOSE(errors, c[i] != a[i] + b[i]);
  }
  OMPVV_REPORT_AND_RETURN(errors);
}

