  for (int i = 0; i < N; i++) {
    device_data[i] = i;
    host_data[i] = 0;
  }
#pragma omp target teams loop defaultmap(tofrom)
  for (int i = 0; i < N; i++) {
    host_data[i] += device_data[i];
    device_data[i] = 2*i;
  }
  // checking results
  for (int i = 0; i < N; i++) {
    OMPVV_TEST_AND_SET(errors, host_data[i] != i);
    OMPVV_TEST_AND_SET(errors, device_data[i] != 2*i);
  }
  return errors;
}

