  // If a list item is an array section, it must specify contiguous storage.
#pragma omp target data map(from: a3d[:N - 2][:2][:2])   \
        map(from: a3d2[:N][:2][:2])
  {
#pragma omp target map(alloc: a3d[:N - 2][:2][:2], a3d2[:N][:2][:2]) // To avoid default mapping tofrom
    {
      for (int i = 0; i < N; ++i) {
