  int sum = 0, errors = 0;
  int *h_array_h = (int *)malloc(N * sizeof(int));
  int *h_array2_h = (int *)malloc(N * sizeof(int));

  for (int i = 0; i < N; ++i) {
    h_array_h[i] = 1;
    h_array2_h[i] = 0;
  }

#pragma omp target data map(to: h_array_h[0:N]) map(from: h_array2_h[0:N])
  {
#pragma omp target
    {
      for (int i = 0; i < N; ++i)
        h_array2_h[i] = h_array_h[i];
    } // end target
  } // end target data

  // checking errors
