  int raiseWarning = 0;

  for (i = 0; i < N; i++) {
    OMPVV_TEST_AND_SET(errors, a[i] != 1 + (NUM_ATTEMPTS - ATTEMPT_THRESHOLD));
    if (warning[i] != 0) {
